# Viva deep redo — slot R3 (part A): STI cases (5)
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — STI chapters (gonorrhoea, urethral
# discharge approach, chancroid complications/diagnosis, donovanosis, LGV/esthiomene, genital warts/podophyllin,
# syndromic management & kits); facts checked with IADVL 5e and NACO RTI/STI technical guidelines (colour kits).
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"
NACO = "NACO National Technical Guidelines on RTI/STI (syndromic management, colour-coded kits)"
KITS = ["Kit 1 Grey — urethral/anorectal discharge, cervicitis: azithromycin 1 g + cefixime 400 mg stat",
        "Kit 2 Green — vaginal discharge: secnidazole 2 g + fluconazole 150 mg stat",
        "Kit 3 White — non-herpetic genital ulcer: benzathine penicillin 2.4 MU IM + azithromycin 1 g",
        "Kit 4 Blue — non-herpetic ulcer, penicillin allergy: doxycycline 100 mg BD × 15 days + azithromycin 1 g",
        "Kit 5 Red — herpetic ulcer: acyclovir 400 mg TDS × 7 days",
        "Kit 6 Yellow — lower abdominal pain: cefixime 400 mg stat + metronidazole 400 mg BD × 14 days + doxycycline 100 mg BD × 14 days",
        "Kit 7 Black — inguinal bubo: doxycycline 100 mg BD × 21 days + azithromycin 1 g stat"]

D = [
dict(case="Anogenital warts", src=f"{PYQ}; {IA} (HPV, genital warts); {NACO}",
 qa=[
 ("What are anogenital warts? Which HPV types?", ["Commonest viral STI — benign epithelial proliferations of anogenital skin and mucosa", "~90% due to low-risk HPV 6 and 11; co-infection with high-risk types (16, 18, 31, 33) possible", "Incubation 3 weeks to 8 months (average 2–3 months); many infections subclinical"]),
 ("Describe the clinical types.", ["Condyloma acuminata: soft, pink, filiform/cauliflower-like papillomas on moist areas (prepuce, frenulum, coronal sulcus, vulva, introitus, perianal)", "Papular (dome-shaped, keratinised — shaft, pubis), flat/macular (cervix — seen with acetic acid), keratotic (dry skin)", "Giant condyloma (Buschke–Löwenstein tumour)", "Intra-meatal, vaginal, cervical, anal canal (anoscopy in receptive anal sex)"]),
 ("What is the acetowhite test?", ["5% acetic acid for 3–5 min turns HPV-infected epithelium white — helps find subclinical lesions; not specific (any inflamed/traumatised skin)"]),
 ("Differential diagnosis.", ["Normal variants: pearly penile papules (rows on corona), vestibular papillae (symmetrical, separate bases), Fordyce spots, sebaceous hyperplasia", "Condyloma lata (secondary syphilis — flat, moist, grey; VDRL positive), molluscum, seborrhoeic keratosis, skin tags, lichen planus, bowenoid papulosis, verrucous carcinoma/SCC, Buschke–Löwenstein tumour"]),
 ("When do you biopsy?", ["Atypical (pigmented, indurated, fixed, ulcerated) lesions, immunocompromised patient, no response or worsening on therapy, older patient"]),
 ("Discuss treatment options.", ["Patient-applied: podophyllotoxin 0.5% solution/0.15% cream twice daily 3 days per week, up to 4 weeks; imiquimod 5% cream 3 times/week overnight up to 16 weeks; sinecatechins 15% (green-tea extract)", "Provider-applied/ablative: cryotherapy (liquid nitrogen) weekly; TCA 80–90%; podophyllin 10–25% in tincture benzoin (wash off after 1–4 h; max 0.5 ml/10 cm² per session); electrocautery, radiofrequency, CO2 laser, scissor excision", "Choice depends on number, size, site, keratinisation, cost, pregnancy"]),
 ("Write a short note on podophyllin (PYQ).", ["Resin from Podophyllum emodi (Indian) or P. peltatum; active podophyllotoxin binds tubulin → arrests mitosis in metaphase → necrosis of wart", "Podophyllin is non-standardised and contains mutagenic flavonoids; podophyllotoxin is purified and safer for self-use", "Toxicity: local erosion; systemic absorption from large areas/mucosa → peripheral neuropathy, myelosuppression, hepatotoxicity, coma", "Contraindicated in pregnancy, on cervix/urethra/anal canal, bleeding lesions"]),
 ("Management in pregnancy.", ["Warts enlarge and become friable; avoid podophyllin, podophyllotoxin, (imiquimod — limited data)", "Cryotherapy, TCA, excision/electrocautery", "Caesarean only if warts obstruct the birth canal or would bleed heavily; risk of juvenile recurrent respiratory papillomatosis in baby is low"]),
 ("What about warts in children?", ["Consider sexual abuse but also vertical transmission (up to 2–3 years), autoinoculation from hand warts, non-sexual household spread; careful history and examination, involve paediatric team"]),
 ("What other evaluation and counselling is needed?", ["Screen for other STIs (HIV, syphilis, hepatitis B), examine partner, Pap smear/HPV test for women (cervical screening), anoscopy if anal warts", "Explain recurrence (~30% within 3 months), condoms reduce but don't eliminate transmission, HPV vaccination"]),
 ("Discuss cervical intraepithelial neoplasia link (PYQ).", ["High-risk HPV (16, 18) E6 binds p53, E7 binds Rb → cell-cycle dysregulation → CIN 1–3 → invasive cancer", "Screening: Pap smear (cytology), HPV DNA test, VIA/VILI (visual inspection in low-resource settings)", "Prevention: HPV vaccine before sexual debut"]),
 ("What is the role of HPV vaccines in genital warts?", ["Quadrivalent and nonavalent vaccines (contain 6, 11) prevent ~90% of genital warts — reduction seen in vaccinated populations (Australia); not therapeutic for existing warts"]),
 ],
 spot=["Acetowhitening — subclinical HPV", "HPV 6/11 — 90% of genital warts", "Pearly penile papules are normal — don't treat"]),

dict(case="Chancroid", src=f"{PYQ}; {IA} (Chancroid); {NACO}",
 qa=[
 ("What is chancroid? Organism?", ["Acute STI with painful genital ulcers and suppurative inguinal lymphadenitis caused by Haemophilus ducreyi — small Gram-negative coccobacillus", "Now rare in India (declined with syndromic management); also causes non-sexual chronic leg ulcers in the tropics/Pacific (yaws-like settings)"]),
 ("Pathogenic factors of H. ducreyi (PYQ).", ["Entry through micro-abrasions; cytolethal distending toxin (cell-cycle arrest, apoptosis), haemolysin, outer-membrane proteins (DsrA serum resistance, LspA anti-phagocytic), pili; incubation 3–7 days"]),
 ("Describe the ulcer.", ["Starts as tender papule → pustule → ulcer in 1–2 days", "Ulcer: painful, soft (not indurated — 'soft sore'), ragged undermined edges, purulent grey-yellow necrotic base that bleeds easily, surrounding erythema; often multiple ('kissing ulcers' by autoinoculation)", "Sites: men — prepuce, frenulum, coronal sulcus; women — fourchette, labia (women may be asymptomatic carriers)"]),
 ("Describe the bubo of chancroid.", ["Painful unilateral inguinal lymphadenitis in ~50%, 1–2 weeks after ulcer; matted, fluctuant, may rupture forming a single sinus/ulcer ('bubonulus')", "Overlying skin red; rupture can produce large inguinal ulcers"]),
 ("Clinical variants.", ["Giant chancroid, serpiginous chancroid, phagedenic chancroid (destructive with secondary anaerobes), follicular, dwarf (small superficial), transient (heals then bubo — mimics LGV), papular (mimics donovanosis/condyloma lata)", "Mixed chancre — chancroid + syphilis together (rolled induration appearing later)"]),
 ("Complications of chancroid (PYQ).", ["Phimosis/paraphimosis, phagedena (tissue destruction), fistula, urethral stricture, bubo rupture and large ulcer", "Increased HIV acquisition and transmission (ulcer breaches mucosa), mixed infection with syphilis"]),
 ("Diagnostic tests (PYQ).", ["Gram stain of ulcer edge/bubo pus: Gram-negative coccobacilli in parallel chains — 'school of fish' or 'railroad track' (low sensitivity)", "Culture on enriched selective media (Nairobi/Mueller–Hinton chocolate agar with vancomycin, 33 °C, CO2) — sensitivity <80%", "Multiplex PCR (H. ducreyi, T. pallidum, HSV) — test of choice", "Exclude syphilis (dark-field, serology at baseline and 3 months) and herpes; HIV test", "CDC probable diagnosis: painful ulcer(s), no T. pallidum evidence, typical lymphadenopathy, HSV test negative"]),
 ("Differentiate chancroid from syphilitic chancre.", ["Chancroid: incubation 3–7 days, multiple, painful, soft, ragged undermined edge, dirty bleeding base, painful suppurating unilateral bubo", "Chancre: 9–90 days, usually single, painless, indurated (button-like), clean base with serous exudate, rubbery painless bilateral non-suppurating nodes"]),
 ("Treatment.", ["Azithromycin 1 g single oral dose OR ceftriaxone 250 mg IM single dose OR ciprofloxacin 500 mg twice daily for 3 days OR erythromycin base 500 mg thrice daily for 7 days", "NACO syndromic: white kit (benzathine penicillin + azithromycin) for non-herpetic ulcer, blue kit if penicillin allergy; black kit for bubo", "Fluctuant bubo: needle aspiration through healthy skin or incision and drainage — do not excise", "Treat partners in last 10 days; review at 3–7 days (ulcers improve symptomatically in 3 days, heal in ~7–14 days)"]),
 ("Why is chancroid less common now?", ["Syndromic management, condom promotion, antibiotics for GUD, sex-worker programmes — WHO considers it nearly eliminated in many regions"]),
 ],
 spot=["Painful soft ragged ulcer with dirty base + suppurating bubo — chancroid", "School-of-fish on Gram stain", "Treat with azithromycin 1 g single dose"]),

dict(case="Genital ulcer disease", src=f"{PYQ}; {IA} (Approach to genital ulcer); {NACO}",
 qa=[
 ("Give the causes of genital ulcers — infective and non-infective (PYQ: differential diagnosis of genital ulcers).", ["STI: herpes genitalis (commonest in India now), primary syphilis, chancroid, donovanosis (granuloma inguinale), LGV", "Other infective: candidal balanitis erosions, scabies, secondary bacterial infection, tuberculosis, amoebiasis, CMV/HIV ulcers", "Non-infective: trauma (zipper, bites, sexual), fixed drug eruption, Behçet's/aphthae, erosive lichen planus, pemphigus vulgaris, SJS, lichen sclerosus erosions, Crohn's disease, pyoderma gangrenosum, Lipschütz ulcer (acute vulvar ulcer, EBV), SCC, Zoon's balanitis, dermatitis artefacta"]),
 ("How do you approach a patient with genital ulcer?", ["History: incubation, number, pain, recurrence, bubo, sexual exposure/partners, drug intake (FDE), systemic symptoms (Behçet's)", "Examination: number, size, edge, base, induration, bleeding on touch, regional lymph nodes (character, uni/bilateral), other mucocutaneous signs", "Investigations: dark-field microscopy, Tzanck/PCR for HSV, Gram stain, Giemsa crush smear (Donovan bodies), serology (VDRL/RPR, TPHA), HIV, biopsy for chronic or atypical", "Treat syndromically if lab not available (NACO kits) and review"]),
 ("Compare the main ulcers in a table-like way.", ["Syphilis: painless, single, indurated, clean base, rubbery bilateral nodes, incubation ~3 weeks", "Herpes: painful, multiple grouped vesicles/small erosions, recurrent, tender bilateral nodes, incubation 2–7 days", "Chancroid: painful, multiple, soft, ragged undermined, dirty base, suppurative unilateral bubo, 3–7 days", "Donovanosis: painless, beefy-red, friable, bleeds on touch, extends by continuity, pseudobubo (subcutaneous granulation, no true node), 8–80 days", "LGV: small transient painless ulcer often missed; later painful bubo with groove sign, 3–30 days"]),
 ("What is donovanosis? (PYQ: granuloma inguinale)", ["Chronic progressive ulcerative STI by Klebsiella granulomatis (Calymmatobacterium); endemic in Papua New Guinea, South Africa, India (rare now)", "Types: ulcerogranulomatous (commonest, beefy red), hypertrophic/verrucous, necrotic, sclerotic/cicatricial", "Complications: pseudoelephantiasis, stenosis, SCC, haematogenous spread to bone/liver", "Treatment: azithromycin 1 g weekly (or 500 mg daily) for at least 3 weeks until healed; doxycycline 100 mg BD alternative"]),
 ("What are Donovan bodies? (PYQ)", ["Intracytoplasmic bipolar-staining ('safety-pin') encapsulated rod-shaped organisms inside large mononuclear cells (macrophages), seen on Giemsa/Leishman-stained crush/tissue smear from ulcer edge — diagnostic of donovanosis"]),
 ("How do you do dark-field microscopy?", ["Clean ulcer with saline, squeeze/abrade to get serous exudate (avoid blood), place on slide with coverslip, examine within 20 min under dark-field condenser", "T. pallidum: thin, tightly coiled, corkscrew motility with flexion at the middle (angulation)", "Not for oral lesions (commensal treponemes); negative after topical/systemic antibiotics — repeat thrice"]),
 ("Serological tests for syphilis — classify.", ["Non-treponemal (cardiolipin): VDRL, RPR — quantitative, used for activity and treatment response (4-fold fall); false positives (biological false positive — pregnancy, SLE, APLA, leprosy, malaria, IV drug use); prozone phenomenon", "Treponemal: TPHA/TPPA, FTA-ABS, EIA/CLIA, rapid immunochromatographic tests — remain positive for life", "Reverse algorithm (treponemal first, then non-treponemal) used in many labs"]),
 ("Treatment of early syphilis.", ["Benzathine penicillin G 2.4 MU IM single dose (after test dose as per local protocol)", "Penicillin allergy (non-pregnant): doxycycline 100 mg BD 14 days (azithromycin 2 g single dose — resistance reported)", "Pregnancy: penicillin only (desensitise if allergic)", "Watch for Jarisch–Herxheimer reaction (fever, myalgia within 24 h); follow VDRL at 3, 6, 12 months"]),
 ("What is syndromic management? Advantages and limitations (PYQ).", ["Treatment based on a clinical syndrome (discharge, ulcer, bubo, lower abdominal pain, scrotal swelling, neonatal conjunctivitis) using flowcharts to cover the common organisms at the first visit", "Advantages: simple, quick, treats at first visit without lab, cost-effective, high cure, wide coverage, partner treatment", "Limitations: overtreatment and overdiagnosis, misses asymptomatic infections, poor for cervical infection in women, encourages resistance, no second-line pathway, no aetiological data"]),
 ("Name the NACO colour-coded kits.", KITS),
 ("What are the '4 Cs' and '5 Cs' of STI management?", ["Compliance, Counselling, Condoms, Contact (partner) tracing — plus Case detection/confidentiality as the 5th", "Also offer HIV and syphilis testing (and hepatitis B)"]),
 ("Why is genital ulcer disease important for HIV?", ["Breach of mucosa and recruitment of CD4 cells increase HIV acquisition 2–5 fold and increase shedding; treating GUD is part of HIV prevention"]),
 ],
 spot=["Painless indurated clean ulcer — syphilis", "Beefy red friable ulcer, pseudobubo — donovanosis (safety-pin Donovan bodies)", "White kit = non-herpetic GUD"]),

dict(case="Gonorrhoea / urethral discharge", src=f"{PYQ}; {IA} (Gonorrhoea, non-gonococcal urethritis); {NACO}; WHO 2024 STI guidelines",
 qa=[
 ("What is gonorrhoea? Organism?", ["STI caused by Neisseria gonorrhoeae — Gram-negative intracellular kidney-shaped diplococcus; infects columnar/cuboidal epithelium (urethra, endocervix, rectum, pharynx, conjunctiva)", "Virulence: pili (attachment, antigenic variation), Opa proteins, porin, IgA1 protease, LOS (endotoxin)"]),
 ("Clinical features in men and women.", ["Men: incubation 2–5 days; dysuria and profuse purulent urethral discharge; meatal oedema; ~10% asymptomatic", "Women: >50% asymptomatic; mucopurulent cervicitis, dysuria, vaginal discharge, intermenstrual bleeding", "Extragenital: rectal (receptive anal sex; proctitis), pharyngeal (mostly silent), ophthalmia"]),
 ("Complications — local and metastatic (PYQ).", ["Men: epididymo-orchitis, prostatitis, periurethral abscess, Littre's gland and Tyson's gland infections, urethral stricture, infertility", "Women: Bartholin abscess, PID (salpingitis → infertility, ectopic pregnancy, chronic pelvic pain), Fitz-Hugh–Curtis perihepatitis", "Disseminated gonococcal infection (DGI, ~1%): arthritis–dermatitis syndrome — fever, tenosynovitis, migratory polyarthralgia, few acral haemorrhagic pustules on a red base; or septic monoarthritis; rarely endocarditis, meningitis (complement C5–C9 deficiency predisposes)", "Ophthalmia neonatorum (2–5 days after birth)"]),
 ("Ophthalmia neonatorum (PYQ).", ["Conjunctivitis in first 4 weeks of life: gonococcal (2–5 days, hyperacute purulent, corneal perforation risk), chlamydial (5–14 days, milder), chemical (silver nitrate, first day)", "Gonococcal treatment: ceftriaxone 25–50 mg/kg IM single dose (max 125 mg) + saline eye irrigation; treat mother and partner", "Prophylaxis: erythromycin/tetracycline eye ointment or povidone-iodine at birth"]),
 ("Approach to a case of urethral discharge (PYQ).", ["History: duration, incubation, nature of discharge, dysuria, sexual exposure and partners, previous episodes, antibiotic use", "Examine: milk the urethra, look at meatus, check epididymis, nodes, other STIs", "Gram stain of urethral smear: >2 (≥2–5) polymorphs per oil-immersion field = urethritis; Gram-negative intracellular diplococci = gonococcal (sensitivity >95% in symptomatic men)", "If no diplococci — non-gonococcal urethritis (Chlamydia trachomatis, Mycoplasma genitalium, Ureaplasma, Trichomonas, HSV, adenovirus)", "First-void urine NAAT for gonorrhoea and chlamydia (most sensitive); culture on Thayer–Martin/modified New York City medium for drug susceptibility", "Syndromic: NACO grey kit (azithromycin 1 g + cefixime 400 mg) to patient and partner"]),
 ("Treatment of uncomplicated gonorrhoea.", ["Ceftriaxone single dose IM (500 mg current CDC/WHO; older guidelines 250 mg) plus treat chlamydia (doxycycline 100 mg BD × 7 days, or azithromycin 1 g) unless chlamydia excluded", "Alternative: cefixime 400–800 mg orally single dose; gentamicin 240 mg IM + azithromycin 2 g", "Abstain until 7 days after treatment and partner treated; test of cure for pharyngeal infection"]),
 ("Discuss drug resistance in gonorrhoea (PYQ).", ["Sequentially lost penicillin (PPNG — plasmid β-lactamase), tetracycline (TRNG), fluoroquinolones (gyrA, parC), and now reduced susceptibility to cephalosporins (penA mosaic alleles) and azithromycin (23S rRNA, mtr efflux)", "Extensively drug-resistant strains reported (ceftriaxone-resistant FC428 clone); WHO priority pathogen", "Responses: higher ceftriaxone dose, culture and susceptibility surveillance (GASP), new oral drugs zoliflodacin and gepotidacin (recently approved in some countries — confirm current status)"]),
 ("Discuss non-gonococcal urethritis (PYQ).", ["Commonest STI syndrome in men in many places; Chlamydia trachomatis serovars D–K (~30–50%), Mycoplasma genitalium (10–25%), Ureaplasma urealyticum, Trichomonas, HSV, adenovirus", "Incubation 1–3 weeks; mild mucoid discharge, dysuria; often asymptomatic", "Complications: epididymitis, reactive arthritis (urethritis, conjunctivitis, arthritis, keratoderma blennorrhagicum, circinate balanitis — HLA-B27), PID/infertility in women", "Treatment: doxycycline 100 mg BD × 7 days (preferred), azithromycin 1 g; M. genitalium — doxycycline then moxifloxacin (resistance-guided)"]),
 ("What is Fitz-Hugh–Curtis syndrome? (PYQ)", ["Perihepatitis complicating PID (Chlamydia > gonorrhoea) — right upper quadrant pain, pleuritic, 'violin-string' adhesions between liver capsule and abdominal wall on laparoscopy; LFT often normal"]),
 ("How do you take a cervical sample?", ["Speculum examination, wipe ectocervix, insert swab 1–2 cm into endocervix, rotate 10–15 seconds; Gram stain less sensitive in women (50%) — prefer NAAT/culture"]),
 ("Differentiate gonococcal and non-gonococcal urethritis clinically.", ["Gonococcal: shorter incubation (2–5 days), abrupt, profuse purulent yellow-green discharge, marked dysuria", "NGU: longer incubation (1–3 weeks), gradual, scanty mucoid/ watery discharge, mild dysuria, often early-morning 'glue' at meatus"]),
 ("What is the Gram stain criterion for urethritis?", ["≥2 polymorphonuclear leucocytes per oil-immersion field (×1000) in urethral smear (some use ≥5), or ≥10 PMN/hpf in first-void urine sediment, or positive leucocyte esterase"]),
 ],
 spot=["Gram-negative intracellular diplococci in pus cells — gonorrhoea", "Acral haemorrhagic pustules + tenosynovitis — DGI", "Grey kit — urethral discharge"],
 note="Ceftriaxone dose: newer guidelines use 500 mg (older 250 mg) — this is one of the open questions for the department."),

dict(case="Lymphogranuloma venereum", src=f"{PYQ}; {IA} (LGV); {NACO}",
 qa=[
 ("What is LGV? Agent?", ["Systemic STI of lymphatic tissue caused by invasive Chlamydia trachomatis serovars L1, L2 (commonest; L2b in MSM proctitis outbreaks), L3", "Obligate intracellular; elementary body (infectious) and reticulate body (replicative)"]),
 ("Describe the three stages.", ["Primary (3–30 days): small painless papule, herpetiform ulcer or urethritis/cervicitis — transient, often unnoticed", "Secondary (2–6 weeks later): inguinal syndrome — painful, usually unilateral inguinal/femoral lymphadenitis, matted, may suppurate with multiple sinuses (unlike single opening in chancroid); fever, malaise, arthralgia, erythema nodosum/multiforme; anorectal syndrome in receptive anal sex/women — haemorrhagic proctocolitis", "Tertiary (late): genitoanorectal syndrome — chronic lymphatic obstruction and fibrosis: esthiomene, elephantiasis of genitals, rectal stricture, fistulae, perianal lymphorrhoids, frozen pelvis"]),
 ("What is the groove sign?", ["Enlarged inguinal nodes above and femoral nodes below the inguinal (Poupart's) ligament separated by a groove — seen in ~20%; suggestive but not diagnostic"]),
 ("What is esthiomene? (PYQ)", ["Chronic progressive hypertrophy and ulceration ('eating away') of the vulva due to lymphatic obstruction from LGV — elephantiasis with ulcers, fistulae; also seen with donovanosis, TB, filariasis", "Management: long antibiotic course + reconstructive surgery (vulvectomy/plastic)"]),
 ("What is the Frei test?", ["Historical intradermal skin test with LGV antigen (delayed hypersensitivity) — obsolete because of poor specificity and safety"]),
 ("Investigations.", ["NAAT (PCR) of ulcer swab, bubo aspirate or rectal swab for C. trachomatis with genotyping for L serovars (best)", "Serology: complement fixation titre ≥1:64 or microimmunofluorescence ≥1:256 supports LGV", "Culture in McCoy cells (rarely done); Giemsa — Gamna–Favre inclusion bodies", "Exclude syphilis, HIV, chancroid"]),
 ("Differential diagnosis of inguinal bubo.", ["Chancroid (painful single opening), syphilis (painless rubbery), donovanosis pseudobubo, herpes (tender small nodes), TB lymphadenitis, plague, cat-scratch disease, lymphoma/metastatic nodes, filariasis, pyogenic lymphadenitis from leg infection, incarcerated hernia"]),
 ("Treatment.", ["Doxycycline 100 mg twice daily for 21 days (drug of choice)", "Alternatives: erythromycin 500 mg four times daily for 21 days (pregnancy), azithromycin 1 g weekly for 3 weeks", "NACO black kit (doxycycline 21 days + azithromycin 1 g) for bubo", "Aspirate fluctuant nodes through healthy skin; do not incise (sinus formation); surgery for late strictures/elephantiasis", "Treat contacts in last 60 days"]),
 ("Differentiate LGV proctitis from inflammatory bowel disease.", ["LGV: MSM/receptive anal sex, rapid onset, rectal pain, tenesmus, mucopurulent bloody discharge, PCR positive, rapid response to doxycycline", "Crohn's: chronic, skip lesions, perianal fistula, granulomas, no infection", "Histology can look similar — always test rectal swab"]),
 ("Complications?", ["Rectal stricture, rectovaginal fistula, lymphoedema/elephantiasis of genitals ('saxophone penis'), esthiomene, infertility, rarely SCC; systemic — hepatitis, pneumonitis, meningitis"]),
 ],
 spot=["Groove sign — LGV", "Esthiomene — chronic ulcerating vulval elephantiasis", "Doxycycline 21 days (black kit)"]),
]
